// Inspect components and fonts
async function main() {
  const out = [];
  // Available Hanken Grotesk font styles
  const fonts = await figma.listAvailableFontsAsync();
  const hanken = fonts.filter(f => f.fontName.family.toLowerCase().includes('hanken'));
  out.push('HANKE N FONTS: ' + hanken.map(f => f.fontName.style).join(' | '));

  const comps = figma.root.findAll(n => n.type === 'COMPONENT' || n.type === 'COMPONENT_SET');
  out.push('TOTAL COMPONENTS: ' + comps.length);

  function fillStr(fills) {
    if (!Array.isArray(fills)) return 'null';
    return fills.map(f => {
      if (f.type === 'SOLID') return 'SOLID ' + (f.color ? [f.color.r,f.color.g,f.color.b].map(c=>Math.round(c*255)).join(',') : '?') + ' ' + (f.opacity !== undefined ? 'a'+f.opacity.toFixed(2) : '');
      if (f.type === 'IMAGE') return 'IMAGE ' + (f.imageRef ? f.imageRef.slice(0,8) : '?') + ' scale=' + (f.scaleMode||'?');
      return f.type;
    }).join(' ; ');
  }
  function fmtColor(c){ return c ? '#' + [c.r,c.g,c.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('') : '?'; }

  function walk(n, depth) {
    const pad = '  '.repeat(depth);
    let rec = { t: n.type, n: n.name, d: depth };
    if (n.type === 'RECTANGLE' || n.type === 'ELLIPSE' || n.type === 'FRAME' || n.type === 'VECTOR' || n.type === 'COMPONENT' || n.type === 'COMPONENT_SET' || n.type === 'INSTANCE') {
      rec.w = Math.round(n.width); rec.h = Math.round(n.height);
    }
    if (n.type === 'TEXT') {
      rec.txt = n.characters.slice(0, 60);
      rec.font = n.fontName ? n.fontName.style : '?';
      rec.size = n.fontSize;
      rec.lh = n.lineHeight && n.lineHeight.unit === 'PIXELS' ? n.lineHeight.value : (n.lineHeight ? n.lineHeight.unit : null);
      rec.ls = n.letterSpacing && n.letterSpacing.value !== undefined ? n.letterSpacing.value : null;
      rec.case = n.textCase || null;
      rec.fill = fillStr(n.fills);
      out.push(JSON.stringify(rec));
      return;
    }
    rec.fill = fillStr(n.fills);
    if (n.strokes && n.strokes.length) rec.stroke = fillStr(n.strokes) + ' w' + (n.strokeWeight && typeof n.strokeWeight === 'number' ? n.strokeWeight : '?');
    if (n.effects && n.effects.length) rec.eff = n.effects.map(e => e.type + (e.visible===false?'(hidden)':'')).join(',');
    if (n.cornerRadius !== undefined && n.cornerRadius !== 0) rec.r = n.cornerRadius;
    if (n.type === 'VECTOR') { rec.vector = true; }
    out.push(JSON.stringify(rec));
    if (n.children) n.children.forEach(c => walk(c, depth+1));
  }

  const wanted = ['Button','Text Field','Photo_','Avatar_','Logo_','Icon_'];
  comps.forEach(c => {
    if (wanted.some(w => c.name.startsWith(w))) {
      out.push('===== COMPONENT: ' + c.name + ' (id ' + c.id + ', ' + Math.round(c.width) + 'x' + Math.round(c.height) + ')');
      c.children.forEach(ch => walk(ch, 1));
    }
  });
  console.log(out.join('\n'));
  figma.closePlugin();
}
