(async () => {
  const log = [];
  const ok = (m) => log.push(m);

  // 1) Switch to workspace page
  const wsPage = figma.root.children.find(p => p.name.indexOf('03') === 0);
  if (!wsPage) throw new Error('Workspace page missing');
  await figma.setCurrentPageAsync(wsPage);
  ok('currentPage=' + figma.currentPage.name);

  // 2) Import Button + Text Field from 02 Components page
  const compsPage = figma.root.children.find(p => p.name.indexOf('02') === 0);
  async function importNamed(name) {
    const found = compsPage.findAll(n => n.name === name && (n.type === 'COMPONENT' || n.type === 'COMPONENT_SET'));
    for (const f of found) {
      const key = f.type === 'COMPONENT_SET' ? f.key : f.key;
      if (!key) continue;
      try {
        const imp = await figma.importComponentByKeyAsync(key);
        imp.name = name + '_local';
        imp.x = 0; imp.y = 0;
        ok('imported ' + name + ' -> ' + imp.id + ' type=' + imp.type);
        return imp;
      } catch (e) { ok('import fail ' + name + ': ' + e.message); }
    }
    ok('NOT FOUND ' + name);
    return null;
  }
  const btn = await importNamed('Button');
  const tf = await importNamed('Text Field');

  // 3) Import all media assets
  const mediaPage = figma.root.children.find(p => p.name.indexOf('04') === 0);
  const mediaNames = [
