    'Icon_Arrow_Diagonal','Icon_Arrow_Left','Icon_Arrow_Right','Icon_Instagram','Icon_RSS','Icon_Twitter','Icon_YouTube'
  ];
  const imported = {};
  const importedKeys = new Set();
  const nodes = mediaPage.findAll(n => mediaNames.indexOf(n.name) >= 0);
  for (const name of mediaNames) {
    const node = nodes.find(n => n.name === name);
    if (!node) { imported[name] = null; ok('media missing ' + name); continue; }
    let key = null;
    if (node.type === 'COMPONENT' || node.type === 'COMPONENT_SET') key = node.key;
    else if (node.type === 'INSTANCE' && node.mainComponent) key = node.mainComponent.key;
    if (!key) { ok('media no key ' + name + ' type=' + node.type); imported[name] = null; continue; }
    if (importedKeys.has(key)) {
      // already imported under another name; find it
      imported[name] = importedKeys.get && null;
      const existing = wsPage.findAll(c => c.type === 'COMPONENT' && c.name === name + '_local');
      imported[name] = existing.length ? existing[0] : null;
      continue;
    }
    try {
      const imp = await figma.importComponentByKeyAsync(key);
      imp.name = name + '_local';
      imp.x = 0; imp.y = 0;
      importedKeys.add(key);
      imported[name] = imp;
      ok('media ' + name + ' -> ' + imp.id);
    } catch (e) { ok('media import fail ' + name + ': ' + e.message); imported[name] = null; }
  }

  throw new Error('IMPORTS ' + JSON.stringify({ log }));
})();

